import { getProgramName } from './program_name.mjs';

const OPTION_ORDER = ['a', 'b', 'c'];

const OPTION_DEFINITIONS = {
  '--a': 'a',
  '--b': 'b',
  '--c': 'c',
};

export class CliExit extends Error {
  constructor(exitCode, output, streamName) {
    super(output);
    this.name = 'CliExit';
    this.exitCode = exitCode;
    this.output = output;
    this.streamName = streamName;
  }
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function buildParseError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`;
}

function isHelpToken(token) {
  return token === '-h' || token === '--help';
}

function isOptionLikeValue(token) {
  if (token === undefined) {
    return true;
  }

  if (token === '--') {
    return true;
  }

  if (token.startsWith('--')) {
    return true;
  }

  return /^-[A-Za-z]/.test(token);
}

function normalizeLongOptionToken(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { name: token, hasInlineValue: false, value: '' };
  }

  return {
    name: token.slice(0, equalsIndex),
    hasInlineValue: true,
    value: token.slice(equalsIndex + 1),
  };
}

export function parseTest4Args(argv = process.argv) {
  const programName = getProgramName(argv);
  const parsed = {};
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = String(argv[index]);

    if (isHelpToken(token)) {
      throw new CliExit(0, buildHelp(programName), 'stdout');
    }

    if (token.startsWith('--')) {
      const optionToken = normalizeLongOptionToken(token);

      if (Object.prototype.hasOwnProperty.call(OPTION_DEFINITIONS, optionToken.name)) {
        const key = OPTION_DEFINITIONS[optionToken.name];

        if (optionToken.hasInlineValue) {
          parsed[key] = optionToken.value;
          continue;
        }

        const nextToken = index + 1 < argv.length ? String(argv[index + 1]) : undefined;
        if (isOptionLikeValue(nextToken)) {
          throw new CliExit(2, buildParseError(programName, `argument ${optionToken.name}: expected one argument`), 'stderr');
        }

        parsed[key] = nextToken;
        index += 1;
        continue;
      }

      extras.push(token);
      continue;
    }

    if (token.startsWith('-') && token.length > 1) {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_ORDER.filter((name) => !Object.prototype.hasOwnProperty.call(parsed, name));
  if (missing.length > 0) {
    const formatted = missing.map((name) => `--${name}`).join(', ');
    throw new CliExit(2, buildParseError(programName, `the following arguments are required: ${formatted}`), 'stderr');
  }

  if (extras.length > 0) {
    throw new CliExit(2, buildParseError(programName, `unrecognized arguments: ${extras.join(' ')}`), 'stderr');
  }

  return parsed;
}

