import { ScheduleValueError } from './schedule_errors.mjs';

const DAILY_TIME_PATTERN = /^\d\d:[0-5]\d(?::[0-5]\d)?$/;

export class Job {
  constructor(interval, unit) {
    this.interval = interval;
    this.unit = unit;
    this.jobFunc = null;
    this.jobArgs = [];
    this.jobKwargs = {};
    this.startDay = 'monday';
    this.atTime = null;
  }

  at(timeText) {
    validateMondayAtTime(timeText);
    this.atTime = timeText;
    return this;
  }

  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=None, args=(), kwargs={})`;
  }
}

class EveryBuilder {
  constructor(interval) {
    this.interval = interval;
  }

  get monday() {
    return new Job(this.interval, 'weeks');
  }
}

export function every(interval = 1) {
  return new EveryBuilder(interval);
}

export function validateMondayAtTime(timeText) {
  const normalized = String(timeText);

  if (!DAILY_TIME_PATTERN.test(normalized)) {
    throw new ScheduleValueError(
      'Invalid time format for a daily job (valid format is HH:MM(:SS)?)',
      514,
    );
  }

  const hours = Number.parseInt(normalized.slice(0, 2), 10);
  if (hours < 0 || hours > 23) {
    throw new ScheduleValueError(
      'Invalid number of hours ({} is not between 0 and 23)',
      547,
    );
  }
}

