import { CliExit, parseTest4Args } from './lib/argparse_like.mjs';
import { formatPythonStyleScheduleError, ScheduleValueError } from './lib/schedule_errors.mjs';
import { every } from './lib/schedule_like.mjs';

function writeTo(streamName, text) {
  if (streamName === 'stdout') {
    process.stdout.write(text);
    return;
  }

  process.stderr.write(text);
}

export function main(argv = process.argv) {
  try {
    const args = parseTest4Args(argv);
    const job = every().monday.at(args.a);
    process.stdout.write(`${String(job)}\n`);
    return 0;
  } catch (error) {
    if (error instanceof CliExit) {
      writeTo(error.streamName, error.output);
      return error.exitCode;
    }

    if (error instanceof ScheduleValueError) {
      process.stderr.write(formatPythonStyleScheduleError(error));
      return 1;
    }

    throw error;
  }
}

const exitCode = main(process.argv);
if (exitCode !== 0) {
  process.exitCode = exitCode;
}

